#!/usr/bin/env node
// Concatenates a range of migrations into one file to paste into the Supabase
// SQL editor.
//
// The bundle is generated, never hand-edited: it is byte-for-byte the same SQL
// that CI applies to a throwaway Postgres and asserts against, so the thing you
// paste into production cannot drift from the thing that was tested.
//
//   node scripts/build-migration-bundle.mjs 0011 0015
//
// Writes supabase/apply-<from>-<to>.sql. That path is deliberately outside
// supabase/migrations/, which CI globs — a bundle in there would apply every
// statement twice.

import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import path from "node:path";

const [from = "0011", to = "0015"] = process.argv.slice(2);

const DIR = path.join(process.cwd(), "supabase", "migrations");
const files = readdirSync(DIR)
  .filter((f) => f.endsWith(".sql"))
  .sort()
  .filter((f) => {
    const n = f.slice(0, 4);
    return n >= from && n <= to;
  });

if (files.length === 0) {
  console.error(`no migrations between ${from} and ${to}`);
  process.exit(1);
}

const rule = "═".repeat(70);
const header = `-- ${rule}
--  Supabase migration bundle — ${files[0]} through ${files[files.length - 1]}
--
--  Paste this whole file into the Supabase SQL editor and run it once.
--
--  Generated by scripts/build-migration-bundle.mjs from the migrations in
--  supabase/migrations/. Do not edit this file: edit the migration and
--  regenerate, or the SQL you run in production stops matching the SQL CI
--  tests.
--
--  Safe to re-run. Every statement is guarded (create or replace, if not
--  exists, drop-then-create for triggers and policies), so applying it twice
--  changes nothing the second time.
--
--  It runs in one transaction: if any statement fails, nothing is applied and
--  you can fix and re-paste.
--
--  Assumes migrations 0001 through ${String(Number(from) - 1).padStart(4, "0")} are already applied.
--
--  Contains:
${files.map((f) => `--    ${f}`).join("\n")}
-- ${rule}

begin;

`;

const body = files
  .map(
    (f) => `
-- ${rule}
--  ${f}
-- ${rule}

${readFileSync(path.join(DIR, f), "utf8").trim()}
`,
  )
  .join("\n");

const footer = `

commit;

-- ${rule}
--  Verification — what this bundle should have left behind.
--  Every row below should read 'ok'.
-- ${rule}
select
  'client_preferences table'                                        as object,
  case when to_regclass('public.client_preferences') is not null
       then 'ok' else 'MISSING' end                                 as status
union all select 'preferences row per client',
  case when (select count(*) from public.clients)
          = (select count(*) from public.client_preferences)
       then 'ok' else 'MISMATCH' end
union all select 'invoices.last_event_at column',
  case when exists (select 1 from information_schema.columns
                    where table_schema='public' and table_name='invoices'
                      and column_name='last_event_at')
       then 'ok' else 'MISSING' end
union all select 'one invoice_paid per invoice (unique index)',
  case when exists (select 1 from pg_indexes
                    where schemaname='public' and indexname='activity_invoice_paid_once')
       then 'ok' else 'MISSING' end
union all select 'attachments size + type limits',
  case when exists (select 1 from storage.buckets
                    where id='attachments' and file_size_limit is not null
                      and allowed_mime_types is not null)
       then 'ok' else 'MISSING' end
union all select 'attachments delete policy',
  case when exists (select 1 from pg_policies
                    where schemaname='storage' and tablename='objects'
                      and policyname='attachments_delete')
       then 'ok' else 'MISSING' end
union all select 'functions the app calls',
  case when (select count(*) from pg_proc p
             join pg_namespace n on n.oid = p.pronamespace
             where n.nspname='public' and p.proname in (
               'update_my_profile','update_my_preferences',
               'analytics_revenue','analytics_activity','analytics_event_mix',
               'analytics_top_clients','analytics_active_clients',
               'clients_idle_since','log_invoice_paid',
               'sync_stripe_invoice','sync_stripe_subscription','assert_bookable'
             )) = 12
       then 'ok' else 'MISSING ONE OR MORE' end;
`;

const out = path.join(
  process.cwd(),
  "supabase",
  `apply-${files[0].slice(0, 4)}-${files[files.length - 1].slice(0, 4)}.sql`,
);
writeFileSync(out, header + body + footer);
console.log(
  `wrote ${path.relative(process.cwd(), out)} (${files.length} migrations, ${
    (header + body + footer).split("\n").length
  } lines)`,
);
